<script setup lang="ts">
import PageHeader from '../components/PageHeader.vue'
import EmptyState from '../components/EmptyState.vue'
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api, errorText, taskLabel, type KnowledgePoint } from '../lib/api'
interface Report { id: string; weekStart: string; weekEnd: string; aiStatus: string | null; stats: { summary: { practiceCount: number; wrongCount: number; accuracy: number; newMistakes: number; reviewsCompleted: number; reviewsSkipped: number; duePending: number; studySeconds: number }; reasonDistribution: { name: string; value: number }[]; weakPoints: KnowledgePoint[]; currentAffairs: { id: string; title: string; source: string; sourceUnverified: boolean }[] }; summary: { overview: string; strengths: string[]; weaknesses: string[]; priorities: string[]; nextWeekPlan: { focus: string; actions: string[] }[]; currentAffairs: { newsId: string; insight: string }[] } | null }
const reports = ref<Report[]>([]), selected = ref(''), error = ref(''), busy = ref(false), loading = ref(true), current = computed(() => reports.value.find(x => x.id === selected.value))
let timer: ReturnType<typeof setInterval> | undefined
async function load() { loading.value = true; try { reports.value = (await api.get<Report[]>('/weekly-reports')).data; if (!selected.value) selected.value = reports.value[0]?.id || ''; error.value = '' } catch (e) { error.value = errorText(e) } finally { loading.value = false } }
async function generate() { busy.value = true; try { const { data } = await api.post('/weekly-reports/generate'); selected.value = data.id; await load() } catch (e) { error.value = errorText(e) } finally { busy.value = false } }
onMounted(() => { load(); timer = setInterval(() => { if (current.value && ['PENDING','PROCESSING'].includes(current.value.aiStatus || '')) load() }, 8000) }); onUnmounted(() => clearInterval(timer))
</script>
<template><PageHeader title="公考学习周报"><template #description><p class="muted">共 {{ reports.length }} 份周报</p></template><button class="button" :disabled="busy" @click="generate">{{ busy ? '正在整理统计…' : '生成 / 更新本周周报' }}</button></PageHeader><p v-if="error" class="error" role="alert">{{ error }}</p><div v-if="reports.length" class="toolbar"><select v-model="selected" aria-label="周报日期"><option v-for="report in reports" :key="report.id" :value="report.id">{{ report.weekStart }} 至 {{ report.weekEnd }}</option></select><button class="button secondary" @click="load">刷新</button></div><p v-if="loading && !reports.length" class="loading-state" role="status">正在读取学习周报…</p><EmptyState v-else-if="!reports.length && !error" title="尚未生成学习周报" description="生成本周练习、复习和用时统计。" icon="calendar"><button class="button secondary" :disabled="busy" @click="generate">生成本周周报</button></EmptyState><template v-if="current"><div class="stat-grid"><div class="stat-card"><span>本周练习</span><strong>{{ current.stats.summary.practiceCount }}<small>道</small></strong></div><div class="stat-card"><span>正确率</span><strong>{{ current.stats.summary.practiceCount ? current.stats.summary.accuracy + '%' : '—' }}</strong></div><div class="stat-card"><span>新增错题</span><strong>{{ current.stats.summary.newMistakes }}<small>道</small></strong></div><div class="stat-card"><span>学习用时</span><strong>{{ Math.round(current.stats.summary.studySeconds / 60) }}<small>分钟</small></strong></div></div><div class="content-grid"><section class="panel"><h2>复习完成情况</h2><p class="reading">已完成 {{ current.stats.summary.reviewsCompleted }} 次<br>跳过 {{ current.stats.summary.reviewsSkipped }} 次<br>统计时仍待复习 {{ current.stats.summary.duePending }} 道</p></section><section class="panel"><h2>高频错因</h2><p v-if="!current.stats.reasonDistribution.length" class="empty">本周统计时没有错因记录。</p><p v-for="reason in current.stats.reasonDistribution" :key="reason.name" class="reading">{{ reason.name }} · {{ reason.value }} 道</p></section><section class="panel"><h2>薄弱知识点</h2><p v-if="!current.stats.weakPoints.length" class="empty">尚未有可统计的练习记录。</p><div v-for="point in current.stats.weakPoints" :key="point.id" class="progress-row"><div>{{ point.name }}<span>{{ point.mastery }}%</span></div><progress :value="point.mastery" max="100"></progress></div></section><section class="panel"><h2>本周收录的时政</h2><p v-if="!current.stats.currentAffairs.length" class="empty">本周未收录时政内容。</p><RouterLink v-for="news in current.stats.currentAffairs" :key="news.id" :to="'/news/' + news.id" class="list-row"><strong>{{ news.title }}</strong><small>{{ news.source }}{{ news.sourceUnverified ? ' · 来源待核实' : '' }}</small></RouterLink></section></div><section class="panel section-gap"><div class="panel-heading"><h2>AI 学习总结</h2><span class="badge">{{ taskLabel(current.aiStatus) }}</span></div><template v-if="current.summary"><p class="reading">{{ current.summary.overview }}</p><div v-for="[title,items] in [['本周做得好的方面',current.summary.strengths],['需留意的问题',current.summary.weaknesses],['建议重点复习',current.summary.priorities]]" :key="String(title)"><h3>{{ title }}</h3><ul class="reading"><li v-for="item in items" :key="String(item)">{{ item }}</li></ul></div><h3>下周训练计划</h3><div v-for="plan in current.summary.nextWeekPlan" :key="plan.focus"><h3>{{ plan.focus }}</h3><ul class="reading"><li v-for="action in plan.actions" :key="action">{{ action }}</li></ul></div><h3 v-if="current.summary.currentAffairs.length">时政学习重点</h3><RouterLink v-for="news in current.summary.currentAffairs" :key="news.newsId" :to="'/news/' + news.newsId" class="list-row reading">{{ news.insight }}</RouterLink></template><p v-else class="empty">统计快照已保存，AI 总结尚未完成。可以在处理进度中查看配置与重试。</p><RouterLink class="text-button" to="/tasks">查看处理进度</RouterLink></section></template></template>
